def endnotemap(self, cache=True):
        """return the endnotes from the docx, keyed to string id."""
        if cache and hasattr(self, '_endnotemap'):
            return self._endnotemap
        endnotes = self.endnotes
        endnotemap = {}
        for endnote in endnotes:
            endnotemap[endnote.id] = endnote
        if cache:
            self._endnotemap = endnotemap
        return endnotemap

